@if (erro()) {
  <ucam-empty-state reason="error" title="Não foi possível abrir sua sessão"
    description="O Portal não confirmou o seu acesso a este sistema. Tente de novo; se continuar, entre outra vez pelo Portal.">
    <ucam-button variant="primary" (click)="tentar()">Tentar de novo</ucam-button>
    <ucam-button variant="ghost" (click)="voltarAoPortal()">Voltar para o Portal</ucam-button>
  </ucam-empty-state>
} @else {
  <div class="ucam-empty" role="status">
    <ucam-icon name="loaderCircle" class="ucam-spinner" />
    <p class="ucam-empty__title">Abrindo o {{ sistema }}…</p>
    <p class="ucam-empty__description">Estamos conferindo sua sessão. Isso leva alguns segundos.</p>
    <ucam-button variant="ghost" (click)="voltarAoPortal()">Voltar para o Portal</ucam-button>
  </div>
}

// Ao abrir a sessão: router.navigateByUrl('/', { replaceUrl: true }) — o token sai do endereço.
